// Normalize and validate support ticket API input
const input = $input.first().json || {};

const client_id = Number(input.client_id ?? input.clientId ?? null);
if (!client_id || !Number.isFinite(client_id)) {
  return [{
    ok: false,
    ticket_created: false,
    error: 'missing_client_id',
    message: 'Missing or invalid client_id.',
    status: 'failed',
    eta: null
  }];
}

const validCategories = ['technical', 'account', 'trading', 'funding', 'complaint', 'verification', 'other'];
let category = String(input.category || 'technical').trim().toLowerCase();
if (!validCategories.includes(category)) category = 'technical';

const validPriorities = ['low', 'medium', 'high', 'urgent'];
let priority = String(input.priority || 'medium').trim().toLowerCase();
if (!validPriorities.includes(priority)) priority = 'medium';

const subject = String(input.subject || '').trim().slice(0, 200);
const description = String(input.description || '').trim().slice(0, 5000);

if (!subject || !description) {
  return [{
    ok: false,
    ticket_created: false,
    error: 'missing_subject_or_description',
    message: 'Both subject and description are required for ticket creation.',
    status: 'failed',
    eta: null
  }];
}

const payload = {
  client_id,
  category,
  priority,
  subject,
  description,
  metadata: {
    issue_type: String(input.issue_type || '').trim() || null,
    platform: String(input.platform || '').trim() || null,
    login: String(input.login || '').trim() || null,
    source: 'ai_bot'
  }
};

return [{
  ok: true,
  client_id,
  category,
  priority,
  subject,
  description,
  payload,
  submitted_at: new Date().toISOString()
}];

const input = $input.first().json || {};

return [{
  ok: false,
  ticket_created: false,
  ticket_id: null,
  status: 'failed',
  eta: null,
  error: String(input.error || 'invalid_input'),
  message: String(input.message || 'Invalid input for support ticket creation.')
}];

// Normalize support ticket API response
const req = $('Normalize Input').item.json || {};
const raw = $input.first().json || {};

if (raw.error) {
  return [{
    ok: false,
    ticket_created: false,
    ticket_id: null,
    status: 'failed',
    eta: null,
    error: 'ticket_api_unavailable',
    message: String(raw.error?.message || raw.error || 'Support ticket API request failed')
  }];
}

let data = raw.data || raw.ticket || raw;
if (Array.isArray(data)) data = data[0] || {};

const ticketId = data.ticket_id || data.ticketId || data.id || data.reference || null;
const responseTimes = {
  urgent: '1-2 hours',
  high: '4-6 hours',
  medium: '12-24 hours',
  low: '24-48 hours'
};

const status = String(data.status || (ticketId ? 'open' : 'failed')).toLowerCase();
const eta = data.eta || data.estimated_response || responseTimes[req.priority] || '24-48 hours';

if (!ticketId) {
  return [{
    ok: false,
    ticket_created: false,
    ticket_id: null,
    status: 'failed',
    eta: null,
    error: 'invalid_api_response',
    message: 'Support ticket API responded without a ticket ID.'
  }];
}

return [{
  ok: true,
  ticket_created: true,
  ticket_id: ticketId,
  status,
  eta,
  category: req.category || null,
  priority: req.priority || null,
  subject: req.subject || null,
  submitted_at: req.submitted_at || new Date().toISOString()
}];
